import{_ as e,c as t,o,ah as p}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/Management2/PART2/17.md","filePath":"ja-jp/Management2/PART2/17.md"}'),r={name:"ja-jp/Management2/PART2/17.md"};function n(s,a,i,_,S,l){return o(),t("div",null,[...a[0]||(a[0]=[p('<p>► 2023/O8</p><h2 id="会社としての仕組みを確立するフェーズに来た" tabindex="-1">会社としての仕組みを確立するフェーズに来た <a class="header-anchor" href="#会社としての仕組みを確立するフェーズに来た" aria-label="Permalink to &quot;会社としての仕組みを確立するフェーズに来た&quot;">​</a></h2><p>#マネジメント #いい空気感 #ポジティブな悩み #再現可能性 #個人格と法人格 #BEFIRST</p><h3 id="「bmsgは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」" tabindex="-1">「BMSGは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」 <a class="header-anchor" href="#「bmsgは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」" aria-label="Permalink to &quot;「BMSGは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」&quot;">​</a></h3><p><strong>2023年、BMSGの快進撃がすさまじい。BE:FIRSTの活躍に加え、MAZZELのデビュー、さらにはNovel Core24年の日本武道館公演を発表し、Aile The Shotaは初のワンマンライブを開催。edhiii boiも11月にワンマンライブを予定する。9月1日にはREIKOがプレデビューを果たし、「THE FIRST」の最終審査に残った10人が全員デビューすることになる。そればかりではない。7月に開かれた「BMSG TRAINEE Showcase2023」ではRUI、TAIKI、KANONも著しい成長を見せ、BMSGの新世代への期待も膨らませた。この状態をSKY-HIはどう見ているのか。</strong></p><p>すごい時期ですよ、アーティストが全員楽しそうっていう。どの現場に行っても空気がいいこと、それを社長の自分が自信を持って言えるという状態が最高ですね。悩みってあってしかるべきものだと思うんですけど、つらいのは何か悩むことじゃなくて、解決しようのない悩みがあることのような気がするんですよね。ネガティブな感情って、なかなか抜け切ってくれないので、そういうのがあるとやっぱアーティストはつらいんですけど、今のBMSGのアーティストに悩みとか葛藤があったとしても、とてもポジティブな悩みですね。ネガティビティーが極限まで薄い状況にできてるのが今のような気がします。ある意味、精神的無双状態ですね。こんないい空気が流れているときは、うれしいサプライズもいくつか起きてくるものなんです。</p><p><strong>経営者として見たときに、この状態をどう捉えているのか。</strong></p><p>会社が会社になれるかどうかのフェーズだなと思います。この調子がいい空気や数字を再現可能なものにできるかどうかっていうのは、大事ですよね。そうしたタイミングだと思っています。</p><p>ここまでBMSGという会社は、パーソナリティーで進んできたところがある。つまり、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけないと考えています。</p><p>例えば、自分が2カ月くらいアジアの違う国にいても、会社のいい状態が保てることが必要です。これがBMSGが今やらなくてはいけない会社としての成長ではないでしょうか。少なくとも来年(2024年)は、僕自身がアジアに直接行かなくてはいけない機会が確実にくると思います。確定していることはありませんが、社長として、アジアでBMSGを浸透させるために行きたいと思っています。そうしたときに少し心配ですよね・・・。でも、この時代はどこにいても連絡も取れるし大丈夫なのかな。</p><p><strong>いよいよ本格的な海外進出が始まるということなのだろうか。</strong></p><p>現実問題として、輸出(グローバルでの活躍)なくして未来はない。</p><p>と思っていますし、そのためには、自分であれBE：FIRSTであれMAZZELであれソロアーティストたちであれ、ツアーで全国を回るようのと同じように現地へ赴く必要も当然出てくるでしょう。けれどでも、拠点はあくまで東京に置きたいし、東京からカルチャーを生成し、発信したいですね。</p>',13)])])}const h=e(r,[["render",n]]);export{d as __pageData,h as default};
